  function getCurrentVersionPrefix() {
    const path = window.location.pathname;
    const versionMatch = path.match(/^(\/docs)?\/v\/([^/]+)\//);
    if (versionMatch) {
      return `/v/${versionMatch[2]}/`;
    }
    return null;
  }

  function filterResultsByVersion(results) {
    const versionPrefix = getCurrentVersionPrefix();

    return results.filter(result => {
      const doc = searchIndex.documentStore.getDoc(result.ref);
      const docPath = new URL(doc.id, window.location.origin).pathname;

      if (versionPrefix) {
        // Viewing versioned docs: only show results from this version
        return docPath.includes(versionPrefix);
      } else {
        // Viewing latest docs: exclude all versioned paths
        return !docPath.match(/\/v\/[^/]+\//);
      }
    });
  }

  function performSearch() {
    const query = searchInput.value.trim();

    if (!query || !searchIndex) {
      searchResults.innerHTML = '';
      return;
    }

    const allResults = searchIndex.search(query, {
      fields: {
        title: { boost: 2 },
        body: { boost: 1 }
      },
      expand: true
    });

    const results = filterResultsByVersion(allResults);

    if (results.length === 0) {
      searchResults.innerHTML = `
        <div class="search__no-results">
          No results found for "<strong>${escapeHtml(query)}</strong>"
        </div>
      `;
      return;
    }

    searchResults.innerHTML = results.slice(0, 10).map((result, index) => {
      const doc = searchIndex.documentStore.getDoc(result.ref);
      const preview = getPreview(doc.body, query);

      return `
        <a href="${doc.id}" class="search__result" data-index="${index}" role="option">
          <div class="search__result-title">${highlightMatch(doc.title, query)}</div>
          <div class="search__result-path">${doc.id}</div>
          ${preview ? `<div class="search__result-preview">${preview}</div>` : ''}
        </a>
      `;
    }).join('');

    selectedIndex = -1;
  }

  function handleSearchKeydown(e) {
    const results = searchResults.querySelectorAll('.search__result');

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      selectedIndex = Math.min(selectedIndex + 1, results.length - 1);
      updateSelection(results);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      selectedIndex = Math.max(selectedIndex - 1, -1);
      updateSelection(results);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (selectedIndex >= 0 && results[selectedIndex]) {
        results[selectedIndex].click();
      }
    }
  }

  function updateSelection(results) {
    results.forEach((result, index) => {
      result.classList.toggle('selected', index === selectedIndex);
      if (index === selectedIndex) {
        result.scrollIntoView({ block: 'nearest' });
      }
    });
  }

  function getPreview(body, query) {
    if (!body) return '';

    const lowerBody = body.toLowerCase();
    const lowerQuery = query.toLowerCase();
    const index = lowerBody.indexOf(lowerQuery);

    if (index === -1) return '';

